<?php if (getenv("APP_ENV") !== "production") { die("ERROR: Production only\n"); } $config = [ "db" => [ "host" => getenv("DB_HOST") ?: "127.0.0.1", "port" => getenv("DB_PORT") ?: "3306", "name" => getenv("DB_DATABASE"), "user" => getenv("DB_USERNAME"), "pass" => getenv("DB_PASSWORD"), ], "site" => [ "url" => "https://denta-price.kz", ], "output" => [ "file" => "/tmp/sitemap-doctors.xml", ], ]; if (empty($config["db"]["name"]) || empty($config["db"]["user"])) { die("ERROR: DB config missing\n"); } try { $pdo = new PDO("mysql:host={$config["db"]["host"]};port={$config["db"]["port"]};dbname={$config["db"]["name"]};charset=utf8mb4", $config["db"]["user"], $config["db"]["pass"], [ PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC, ]); } catch (PDOException $e) { die("DB error: " . $e->getMessage() . "\n"); } $sql = "SELECT id, CONCAT(\"doctor/\", id) AS slug, address, district, city, lat, lng FROM doctors WHERE status = \"active\" AND address IS NOT NULL AND address != \"\" ORDER BY id"; $stmt = $pdo->query($sql); $doctors = $stmt->fetchAll(); if (empty($doctors)) { die("No active doctors with addresses\n"); } $xml = new DOMDocument("1.0", "UTF-8"); $xml->formatOutput = true; $urlset = $xml->createElement("urlset"); $urlset->setAttribute("xmlns", "http://www.sitemaps.org/schemas/sitemap/0.9"); $urlset->setAttribute("xmlns:geo", "http://www.google.com/schemas/sitemap-geo/1.0"); $xml->appendChild($urlset); foreach ($doctors as $doctor) { $url = $xml->createElement("url"); $loc = $xml->createElement("loc", $config["site"]["url"] . "/" . $doctor["slug"]); $url->appendChild($loc); $geoLocation = $xml->createElement("geo:location"); $geoFormat = $xml->createElement("geo:format", "address"); $geoLocation->appendChild($geoFormat); $addressParts = array_filter([ $doctor["city"], $doctor["district"], $doctor["address"] ]); $fullAddress = implode(", ", $addressParts); $geoAddress = $xml->createElement("geo:address", $fullAddress); $geoLocation->appendChild($geoAddress); if (!empty($doctor["lat"]) && !empty($doctor["lng"])) { $geoPoint = $xml->createElement("geo:point", $doctor["lat"] . " " . $doctor["lng"]); $geoLocation->appendChild($geoPoint); } $url->appendChild($geoLocation); $urlset->appendChild($url); } $tmpFile = $config["output"]["file"]; $xml->save($tmpFile); echo "Sitemap created: $tmpFile\n"; echo "Doctors added: " . count($doctors) . "\n";
